    public function listAssets(): Envelope { $raw=$this->request('GET','/v1/assets'); return new Envelope(array_map([Asset::class,'fromArray'],$raw['data']['items']),$raw['request_id'],$raw['api_version']); }
    public function submitPaymentProof(SubmitPaymentProofRequest $value, string $key): Envelope { return $this->proofEnvelope($this->request('POST','/v1/payment-proofs',$value->toArray(),[],$key)); }
    public function getPaymentProof(string $id): Envelope { return $this->proofEnvelope($this->request('GET','/v1/payment-proofs/'.rawurlencode($id))); }
    public function listEvents(int $afterSequence = 0, int $limit = 100): Envelope { $raw=$this->request('GET','/v1/events',null,['after_sequence'=>$afterSequence,'limit'=>$limit]); return new Envelope(new EventPage($raw['data']['items'],$raw['data']['next_cursor'],$raw['data']['next_sequence']),$raw['request_id'],$raw['api_version']); }
