    public function listTransfers(?string $after=null,int $limit=50): Envelope{return $this->pageEnvelope($this->request('GET','/v1/transfers',null,['after'=>$after,'limit'=>$limit]));}
    public function getTransferEvents(string $network,string $transactionId): Envelope{$raw=$this->request('GET','/v1/transfers/'.rawurlencode($network).'/'.rawurlencode($transactionId));return new Envelope($raw['data']['items'],$raw['request_id'],$raw['api_version']);}
    public function listQuotes(?string $after=null,int $limit=50): Envelope{return $this->pageEnvelope($this->request('GET','/v1/quotes',null,['after'=>$after,'limit'=>$limit]));}
    public function getQuote(string $id): Envelope{return $this->mappingEnvelope($this->request('GET','/v1/quotes/'.rawurlencode($id)));}
    public function listBalances(): Envelope{$raw=$this->request('GET','/v1/balances');return new Envelope($raw['data']['items'],$raw['request_id'],$raw['api_version']);}
    public function getReconciliation(): Envelope{return $this->mappingEnvelope($this->request('GET','/v1/reconciliation'));}
    public function createReconciliationReport(CreateReconciliationReportRequest $value,string $key): Envelope{return $this->mappingEnvelope($this->request('POST','/v1/reconciliation-reports',$value->toArray(),[],$key));}
    public function getReconciliationReport(string $id): Envelope{return $this->mappingEnvelope($this->request('GET','/v1/reconciliation-reports/'.rawurlencode($id)));}
