    public function createPaymentLink(array $value,string $key): array{return $this->request('POST','/v1/payment-links',$value,[],$key);}
    public function listPaymentLinks(?string $cursor=null,int $limit=50): array{return $this->request('GET','/v1/payment-links',null,['cursor'=>$cursor,'limit'=>$limit]);}
    public function getPaymentLink(string $id): array{return $this->request('GET','/v1/payment-links/'.rawurlencode($id));}
