    private function download(string $path): ReportDownload{$maximum=268435456;$signed=Signing::request($this->keyId,$this->secret,'GET',$path,'',time(),bin2hex(random_bytes(16)));$headers=['Accept: application/x-ndjson'];foreach($signed->toArray()as$key=>$value)$headers[]=$key.': '.$value;$context=stream_context_create(['http'=>['method'=>'GET','header'=>implode("\r\n",$headers),'timeout'=>900,'ignore_errors'=>true,'follow_location'=>0,'max_redirects'=>0]]);$stream=@fopen(rtrim($this->baseUrl,'/').$path,'rb',false,$context);if($stream===false)throw new MerchantApiException(0,'transport_error','report download failed',retryable:true);$metadata=stream_get_meta_data($stream);$status=0;$responseHeaders=[];foreach($metadata['wrapper_data']??[]as$line){if(preg_match('/^HTTP\/\S+\s+(\d+)/',$line,$match))$status=(int)$match[1];elseif(str_contains($line,':')){[$key,$value]=explode(':',$line,2);$responseHeaders[strtolower(trim($key))]=trim($value);}}if($status!==200){fclose($stream);throw new MerchantApiException($status,'report_unavailable','reconciliation report unavailable',retryable:$status===429||$status>=500);}$raw='';while(!feof($stream)){$chunk=fread($stream,1048576);if($chunk===false){fclose($stream);throw new MerchantApiException(0,'transport_error','report download failed',retryable:true);}$raw.=$chunk;if(strlen($raw)>$maximum){fclose($stream);throw new MerchantApiException(200,'report_too_large','reconciliation report exceeds configured client limit');}}fclose($stream);$digest=$responseHeaders['x-reconciliation-sha256']??'';$signature=$responseHeaders['x-reconciliation-signature']??'';$keyId=$responseHeaders['x-reconciliation-signing-key-id']??'';if(!preg_match('/^[0-9a-f]{64}$/',$digest)||$signature===''||$keyId==='')throw new MerchantApiException(200,'invalid_response','missing reconciliation integrity headers');return new ReportDownload($raw,$digest,$signature,$keyId);}
    private function intentEnvelope(array $raw): Envelope{return new Envelope(PaymentIntent::fromArray($raw['data']),$raw['request_id'],$raw['api_version']);}
    private function proofEnvelope(array $raw): Envelope{return new Envelope(PaymentProof::fromArray($raw['data']),$raw['request_id'],$raw['api_version']);}
    private function mappingEnvelope(array $raw): Envelope{return new Envelope($raw['data'],$raw['request_id'],$raw['api_version']);}
    private function pageEnvelope(array $raw): Envelope{return new Envelope(new CursorPage($raw['data']['items'],$raw['data']['next_cursor']??''),$raw['request_id'],$raw['api_version']);}
    public static function validateBaseUrl(string $value): void{$parts=parse_url($value);$host=$parts['host']??'';$loopback=($parts['scheme']??'')==='http'&&in_array($host,['localhost','127.0.0.1'],true);if($host===''||(($parts['scheme']??'')!=='https'&&!$loopback)||isset($parts['user'])||isset($parts['pass'])||isset($parts['query'])||isset($parts['fragment'])||(isset($parts['path'])&&!in_array($parts['path'],['','/'],true)))throw new \InvalidArgumentException('base URL must be an HTTPS origin');}
