final class CheckoutClient {
    public function __construct(private readonly string $baseUrl,private readonly float $timeoutSeconds=10.0){Client::validateBaseUrl($baseUrl);}
    public function getSession(string $token): CheckoutSession {
        if(!preg_match('/^cs_[A-Za-z0-9_-]{43}$/',$token))throw new \InvalidArgumentException('invalid checkout token');
        $context=stream_context_create(['http'=>['method'=>'GET','header'=>'Accept: application/json','timeout'=>$this->timeoutSeconds,'ignore_errors'=>true,'follow_location'=>0,'max_redirects'=>0]]);$raw=@file_get_contents(rtrim($this->baseUrl,'/').'/v1/checkout-sessions/'.rawurlencode($token),false,$context);$status=0;foreach($http_response_header??[]as$line)if(preg_match('/^HTTP\/\S+\s+(\d+)/',$line,$match))$status=(int)$match[1];
        if($raw===false||$status!==200)throw new MerchantApiException($status,'checkout_unavailable','checkout session unavailable',retryable:$status===429||$status>=500);
        try{$value=json_decode($raw,true,512,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new MerchantApiException(200,'invalid_response','invalid checkout response');}$statuses=['pending','detected','confirming','settled','expired','preparing_payment_route','payment_route_failed'];if(!in_array($value['status']??'', $statuses,true)||!is_array($value['routes']??null)||!is_string($value['selected_route_id']??null))throw new MerchantApiException(200,'invalid_response','invalid checkout response');$waiting=in_array($value['status'],['preparing_payment_route','payment_route_failed'],true);if(($waiting&&($value['routes']!==[]||$value['selected_route_id']!==''))||(!$waiting&&$value['routes']===[]))throw new MerchantApiException(200,'invalid_response','invalid checkout response');
        $routes=[];foreach($value['routes']as$route){$provider=$route['provider']??'';$onChain=$provider==='on_chain'&&isset($route['network'],$route['address'])&&!isset($route['payment_url']);$hosted=$provider==='hosted_gateway'&&isset($route['provider_id'],$route['payment_url'])&&!isset($route['network'],$route['address'])&&str_starts_with((string)$route['payment_url'],'https://');if(!isset($route['id'],$route['asset'],$route['amount'])||(!$onChain&&!$hosted)||!preg_match('/^\d+(\.\d+)?$/',(string)$route['amount']))throw new MerchantApiException(200,'invalid_response','invalid checkout route');$routes[]=new CheckoutRoute((string)$route['id'],$provider,(string)$route['asset'],(string)$route['amount'],$onChain?(string)$route['network']:null,$onChain?(string)$route['address']:null,$hosted?(string)$route['provider_id']:null,$hosted?(string)$route['payment_url']:null,isset($route['transaction_hash'])?(string)$route['transaction_hash']:null,isset($route['explorer_url'])?(string)$route['explorer_url']:null);}
        if($value['selected_route_id']!==''&&!array_filter($routes,static fn($route)=>$route->id===$value['selected_route_id']))throw new MerchantApiException(200,'invalid_response','invalid selected checkout route');return new CheckoutSession($value['intent_id'],$value['order_id'],$value['status'],$value['expires_at'],$value['selected_route_id'],$routes);
    }
    public function getPaymentLink(string $token): array{return $this->publicRequest('GET','/v1/public/payment-links/'.rawurlencode($this->token($token,'pl')));}
    public function redeemPaymentLink(string $token,string $key,array $value=[],?string $origin=null): array{return $this->publicRequest('POST','/v1/public/payment-links/'.rawurlencode($this->token($token,'pl')).'/redeem',$value,$key,$origin);}
    public function selectRoute(string $token,string $routeId,string $key,?string $origin=null): array{return $this->publicRequest('POST','/v1/checkout-sessions/'.rawurlencode($this->token($token,'cs')).'/select-route',['route_id'=>$routeId],$key,$origin);}
    private function token(string $value,string $prefix): string{if(!preg_match('/^'.preg_quote($prefix,'/').'_[A-Za-z0-9_-]{43}$/',$value))throw new \InvalidArgumentException('invalid capability token');return $value;}
    private function publicRequest(string $method,string $path,?array $value=null,?string $key=null,?string $origin=null): array{$body=$value===null?null:json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$headers=['Accept: application/json'];if($body!==null)$headers[]='Content-Type: application/json';if($key!==null)$headers[]='Idempotency-Key: '.$key;if($origin!==null)$headers[]='Origin: '.$origin;$context=stream_context_create(['http'=>['method'=>$method,'header'=>implode("\r\n",$headers),'content'=>$body??'','timeout'=>$this->timeoutSeconds,'ignore_errors'=>true,'follow_location'=>0,'max_redirects'=>0]]);$raw=@file_get_contents(rtrim($this->baseUrl,'/').$path,false,$context);$status=0;foreach($http_response_header??[]as$line)if(preg_match('/^HTTP\/\S+\s+(\d+)/',$line,$match))$status=(int)$match[1];if($raw===false||$status<200||$status>=300)throw new MerchantApiException($status,'checkout_unavailable','public checkout request failed',retryable:$status===429||$status>=500);return json_decode($raw,true,512,JSON_THROW_ON_ERROR);}
}
